// recipe: ui-modal
// args: none
// returns: ok, modal, nonModalEscape, spectator, error, detail
// Reads the CUO surface's own modal flag: `PlayerCamera.HandleInput` returns at its first line while the Online UI
// window is modal, so a key the harness staged looks exactly like a key the game ignored. `PatchBridge.SessionSurface`
// is the object that flag lives on (`OnlineMenuInputGuard.IsOnlineUiModalOpen`).
((System.Func<string>)(() => { var findType = new System.Func<string, System.Type>((simpleName) => { foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) { var found = assembly.GetType("CasualtiesUnknownOnline.GameAdapter." + simpleName, false); if (found != null) { return found; } } return null; }); var bridgeType = findType("PatchBridge"); if (bridgeType == null) { return "{\"ok\":false,\"error\":\"no-bridge\"}"; } var surface = bridgeType.GetProperty("SessionSurface", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)?.GetValue(null); if (surface == null) { return "{\"ok\":true,\"modal\":false,\"nonModalEscape\":false,\"detail\":\"no surface\"}"; } var surfaceType = surface.GetType(); var modal = surfaceType.GetProperty("IsOnlineUiModalOpen")?.GetValue(surface); var escape = surfaceType.GetProperty("IsNonModalEscapeSurfaceOpen")?.GetValue(surface); var gateType = (System.Type)null; foreach (var assembly in System.AppDomain.CurrentDomain.GetAssemblies()) { var found = assembly.GetType("CasualtiesUnknownOnline.GameAdapter.Capabilities.SpectatorPresentationGate", false); if (found != null) { gateType = found; break; } } var spectator = gateType?.GetProperty("IsActive", System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic)?.GetValue(null); return "{\"ok\":true,\"modal\":" + (modal is bool m && m ? "true" : "false") + ",\"nonModalEscape\":" + (escape is bool e && e ? "true" : "false") + ",\"spectator\":" + (spectator is bool s && s ? "true" : "false") + "}"; }))()
